import {FIELD_MODES,fieldHours,withinField,rangeBounds} from './map-field-core.js';
import {mapIcon} from './map-visuals.js';
import {distanceText,rankShelters,directionsURL} from './nearby-tools.js';

// Owns local exploration, never starts an AI request or reads GPS automatically.
export function createFieldDesk(o){
 const {$,esc,L,map,api}=o,layer=L.layerGroup().addTo(map),rings=L.layerGroup().addTo(map),drafts=new Map(),cache=new Map();
 let key='',mode='temperature',place=null,radius=150,posts=[],reportState='loading',truncated=false,forecast=null,weatherState='loading',life=0,dead=false,open=false,places=[],shelterToken=0,refreshAt=0,expiryTimer;
 const current=()=>FIELD_MODES[mode],near=()=>place?withinField(posts,place,radius):[],time=t=>new Date(t).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit',timeZone:forecast?.timezone||undefined}),fmt=n=>Number.isFinite(n)?n.toLocaleString('it-IT',{maximumFractionDigits:1}):'—';
 const pending=new Map();let cacheGeneration=0;
 const clearCache=()=>{cacheGeneration++;cache.clear();pending.clear();};
 const cached=async(k,fn)=>{const r=cache.get(k);if(r&&Date.now()-r.at<120000)return r.value;if(pending.has(k))return pending.get(k);const generation=cacheGeneration,task=fn().then(value=>{if(generation===cacheGeneration){cache.set(k,{at:Date.now(),value});if(cache.size>35)cache.delete(cache.keys().next().value);}return value;}).finally(()=>{if(pending.get(k)===task)pending.delete(k);});pending.set(k,task);return task;};
 function sync(p,m){
  if(!p||dead)return;const next=[p.latitude.toFixed(3),p.longitude.toFixed(3),m].join(':');
  if(next===key&&Date.now()-refreshAt<120000)return;
  const changed=next!==key;key=next;place={...p};mode=m;refreshAt=Date.now();const token=++life;
  if(changed){posts=[];places=[];shelterToken++;forecast=null;}reportState='loading';weatherState='loading';render();draw();
  const lat=Math.round(place.latitude*100)/100,lon=Math.round(place.longitude*100)/100;
  cached('reports:'+key,()=>api('atlas/field-reports?'+new URLSearchParams({lat,lon,layer:mode,radius:150}))).then(d=>{if(dead||token!==life)return;posts=d.posts||[];truncated=!!d.truncated;reportState='ok';render();draw();}).catch(()=>{if(dead||token!==life)return;reportState='error';render();draw();});
  const wxkey=lat+':'+lon;
  cached('weather:'+wxkey,()=>api('forecast?'+new URLSearchParams({lat,lon}))).then(d=>{if(dead||token!==life)return;forecast=d;weatherState='ok';render();}).catch(()=>{if(dead||token!==life)return;weatherState='error';render();});
 }
 function render(){
  const slot=$('#mappa-field');if(!slot||dead||!place)return;const focusId=slot.contains(document.activeElement)?document.activeElement.id:null;
  if(mode==='grandine'){const count=$('[data-conteggio="grandine"]');if(count)count.textContent=reportState==='ok'?near().length+(truncated?'+':''):'—';}
  const config=current(),list=near(),hours=fieldHours(forecast),closest=list.find(p=>!p.ended),stormHours=hours.filter(h=>[95,96,99].includes(h.weather_code));
  slot.classList.toggle('is-open',open);slot.innerHTML=`<button class="field-mobile-handle" aria-expanded="${open}" id="field-expand"><span>${mapIcon(mode)} ${esc(config.name)} · ${esc(place.name)}</span><b>${open?'−':'Esplora +'}</b></button><div class="field-content"><div class="field-eyebrow">OSSERVATORIO LOCALE <span>${mapIcon(mode)}</span></div><h2>${config.title}</h2><p class="field-location">${esc(place.name)}</p>${mode==='grandine'?`<div class="field-range-stat"><strong>${radius}<small> km</small></strong><span>raggio di ricerca<br>centrato sulla zona scelta</span></div><div class="field-radius" role="group" aria-label="Raggio di ricerca grandine">${[25,50,100,150].map(n=>`<button id="field-radius-${n}" data-field-radius="${n}" aria-pressed="${radius===n}">${n} km</button>`).join('')}</div><p class="field-note">${reportState==='loading'?'Cerco osservazioni…':reportState==='error'?'Segnalazioni non disponibili.':closest?'Più vicina: circa '+distanceText(closest.distance)+'.':'Nessuna osservazione attiva nel campione.'} Distanza in linea d’aria, non tempo di arrivo.</p><button id="field-frame" class="field-wide">Inquadra i ${radius} km ${mapIcon('locate')}</button>`:weatherState==='loading'?'<p class="field-loading" role="status">Leggo le prossime 6 ore…</p>':weatherState==='error'||!hours.length?'<p class="field-note">Andamento orario non disponibile. Puoi riprovare con Aggiorna dati.</p>':`<div class="field-hours" aria-label="Previsioni delle prossime sei ore">${hours.map(h=>`<div><time>${time(h.time)}</time><i style="--bar:${bar(h)}%" aria-hidden="true"></i><b>${mode==='fulmini'?h.weather_code===null?'—':[95,96,99].includes(h.weather_code)?'ϟ':'·':fmt(h[config.field])}</b><small>${mode==='fulmini'?h.weather_code===null?'N/D':[95,96,99].includes(h.weather_code)?'Temporale':'Modello':config.unit.trim()||'°C'}</small></div>`).join('')}</div><p class="field-note">${mode==='fulmini'?`${stormHours.length} ore con temporale nel campione. Le scariche reali non sono rilevate.`:config.extra?`${config.extraLabel}: ${fmt(max(hours,config.extra))}${mode==='temperature'?'°':mode==='pioggia'?'%':' km/h'} al massimo nelle ore mostrate.`:''}</p><p class="field-source">Open-Meteo${forecast._offline?' · copia precedente del '+new Date(forecast._loadedAt).toLocaleString('it-IT'):''} · ${esc(forecast.timezone||'ora locale')}${mode==='pioggia'?' · quantità per ora':''}</p>`}<div class="field-actions"><button id="field-report" aria-label="Segnala ${config.name.toLowerCase()}">${mapIcon('plus')} Segnala</button><button id="field-reports" aria-label="Osservazioni di ${config.name.toLowerCase()} nel raggio scelto">${mapIcon('list')} ${reportState==='ok'?list.length+(truncated?'+':''):'—'} report <span>↗</span></button><button id="field-shelters" aria-label="Trova punti coperti entro 5 km">${mapIcon('shelter')} Ripari</button><button id="field-ai" class="field-ai" title="${esc(config.question)}" aria-label="Leggi ${config.name.toLowerCase()} con Lente IA">${mapIcon('ai')} Lente IA</button></div><p class="field-footnote">${mode==='grandine'?'Community · ultime 2 ore. Nessuna segnalazione non significa assenza di rischio.':'Previsioni + voci dal posto. Le osservazioni sono non verificate e restano visibili per 2 ore.'}</p></div>`;
  $('#field-expand').onclick=()=>{open=!open;render();};
  slot.querySelectorAll('[data-field-radius]').forEach(b=>b.onclick=()=>{radius=Number(b.dataset.fieldRadius);render();draw();frame();});
  if($('#field-frame'))$('#field-frame').onclick=frame;
  $('#field-report').onclick=report;$('#field-reports').onclick=reportList;$('#field-shelters').onclick=()=>shelters('car');$('#field-ai').onclick=()=>{open=false;render();o.askAI(config.question);};if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});o.labelsChanged();
 }
 const max=(hours,field)=>{const values=hours.map(h=>h[field]).filter(Number.isFinite);return values.length?Math.max(...values):null;};
 function bar(h){const n=h[current().field];if(!Number.isFinite(n))return 0;if(mode==='temperature')return Math.max(5,Math.min(100,(n+10)*2));if(mode==='pioggia')return Math.min(100,n*12);if(mode==='vento')return Math.min(100,n*1.5);return [95,96,99].includes(n)?90:8;}
 function frame(){open=false;render();map.fitBounds(rangeBounds(place,radius),{paddingTopLeft:matchMedia('(max-width:920px)').matches?[25,215]:[315,170],paddingBottomRight:[90,165],animate:!matchMedia('(prefers-reduced-motion:reduce)').matches,maxZoom:9});}
 function draw(){
  layer.clearLayers();rings.clearLayers();if(!place||dead)return;
  if(mode==='grandine')for(const km of [50,100,150].filter(n=>n<=radius).concat([25].filter(n=>radius===n))){
   L.circle([place.latitude,place.longitude],{radius:km*1000,color:'#ffad80',weight:km===radius?1.5:1,opacity:km===radius?.7:.35,dashArray:km===radius?'3 6':'2 10',fillColor:'#fc995e',fillOpacity:km===radius?.035:0,interactive:false}).addTo(rings);
   const b=rangeBounds(place,km);L.marker([b[1][0],place.longitude],{interactive:false,keyboard:false,icon:L.divIcon({className:'field-range-label',html:km+' km',iconSize:[60,22],iconAnchor:[30,11]})}).addTo(rings);
  }
  for(const p of near()){
   const pin=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'field-report-pin'+(p.ended?' is-ended':''),html:mapIcon(mode)+'<i></i>',iconSize:[36,40],iconAnchor:[18,32]}),title:p.city+' · osservazione '+current().name,alt:p.city+', segnalazione '+current().name});pin.on('click',()=>reportDetail(p));layer.addLayer(pin);pin.getElement()?.setAttribute('aria-label',p.city+', segnalazione '+current().name);
  }
  for(const p of places){const pin=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'field-shelter-pin',html:mapIcon('shelter'),iconSize:[40,40],iconAnchor:[20,20]}),title:p.name,alt:p.name+', punto coperto da verificare'});pin.on('click',()=>shelterDetail(p));layer.addLayer(pin);pin.getElement()?.setAttribute('aria-label',p.name+', punto coperto da verificare');}
 }
 function reportList(){
  open=false;render();const list=near();o.panel('Osservazioni · '+current().name,`<p>Entro ${radius} km da ${esc(place.name)} · ultime 2 ore · posizioni approssimate</p><div class="field-report-list">${reportState==='error'?'<p>Impossibile recuperare le segnalazioni. Riprova.</p>':list.map((p,i)=>`<button data-field-post="${i}"><span><b>${esc(p.city)}</b><small>${Math.max(0,Math.floor((Date.now()-p.observed)/60000))} min fa · ${p.ended?'cessata per l’autore':'non verificata'}</small></span><strong>~${distanceText(p.distance)}</strong></button>`).join('')||'<p>Nessuna osservazione nel campione. Non è una conferma di cielo sereno.</p>'}</div>${truncated?'<p>Campione parziale: ci sono altre osservazioni. Il conteggio non rappresenta tutti i report.</p>':''}<button class="mappa-primary" id="field-list-report">Aggiungi la tua osservazione</button>`);$('#field-list-report').onclick=report;document.querySelectorAll('[data-field-post]').forEach(b=>b.onclick=()=>reportDetail(list[+b.dataset.fieldPost]));
 }
 function reportDetail(p){
  o.panel(p.city+' · '+current().name,`<p class="field-note">Community · non verificata · ${new Date(p.observed).toLocaleString('it-IT')}</p><p>${esc(p.text)}</p><p>Circa ${distanceText(p.distance)} dalla zona selezionata. Posizione arrotondata, non distanza da un fronte meteo.</p>${p.ended?'<p>L’autore ha indicato che il fenomeno è cessato dal suo punto di osservazione.</p>':''}<button id="field-post-community">Apri la community ↗</button>`);$('#field-post-community').onclick=()=>o.openPlace({...place,name:p.city,latitude:p.latitude,longitude:p.longitude},'community');
 }
 function report(){
  if(!o.get().me)return o.login();const p={...place},config=current(),draftKey=key,d=drafts.get(draftKey)||{id:crypto.randomUUID(),text:'',city:p.source==='gps'?'':p.name};drafts.set(draftKey,d);
  o.modal('Segnala '+config.name.toLowerCase(),`<p>Racconta solo ciò che stai osservando da un posto protetto.</p><label class="field"><span>Comune della zona scelta</span><input id="field-report-city" ${p.source==='gps'?'':'readonly'} required maxlength="80" value="${esc(d.city)}"></label><label class="field"><span>La tua osservazione</span><textarea id="field-report-text" required maxlength="1000" placeholder="Es. Raffiche forti sul lungomare">${esc(d.text)}</textarea></label><label class="scanner-consent"><input id="field-report-consent" type="checkbox" required> Confermo di aver osservato il fenomeno adesso nella zona scelta. Pubblica il testo e la posizione approssimata a circa 1 km per 2 ore.</label><p>Centro selezionato: ${esc(p.name)}. Per un’altra zona, chiudi e cercala sulla mappa. Non inviamo questo report all’IA.</p>`,async()=>{
   if(!$('#field-report-consent').checked)return false;
   await api('posts',{id:d.id,kind:config.kind,text:d.text,city:d.city,rapid:true,mapPoint:{latitude:p.latitude,longitude:p.longitude,consent:true}});
   drafts.delete(draftKey);clearCache();key='';sync(place,mode);o.toast('Osservazione pubblicata nella mappa e nella community per 2 ore.');return true;
  });$('#confirm-dialog').textContent='Pubblica osservazione';$('#field-report-text').oninput=e=>d.text=e.target.value;$('#field-report-city').oninput=e=>d.city=e.target.value;
 }
 async function shelters(category){
  const p={...place},token=++shelterToken;open=false;render();places=[];draw();o.panel('Punti coperti · '+p.name,'<p role="status">Cerco luoghi nel raggio di 5 km…</p><p>La ricerca usa una posizione arrotondata. Accesso, copertura e posti liberi vanno verificati.</p>');const panelToken=o.panelToken();
  try{
   const lat=Math.round(p.latitude*100)/100,lon=Math.round(p.longitude*100)/100,d=await cached('shelters:'+lat+':'+lon+':'+category,()=>api('pulse/nearby?'+new URLSearchParams({lat,lon,category})));
   if(dead||token!==shelterToken||panelToken!==o.panelToken())return;
   places=rankShelters(d.places||[],p,category,5);const unknown=rankShelters(d.places||[],p,'all',5).filter(x=>x.type==='unknown');places.push(...unknown);places.sort((a,b)=>a.distance-b.distance);draw();
   o.panel('Punti coperti · '+p.name,`<div class="field-radius"><button data-shelter-type="car" aria-pressed="${category==='car'}">Auto</button><button data-shelter-type="people" aria-pressed="${category==='people'}">A piedi</button></div><p>Entro 5 km dal centro selezionato. Distanze in linea d’aria, posti liberi non disponibili.</p>${d.sourceError?'<p class="field-warning">'+esc(d.sourceError)+'</p>':''}<div class="field-report-list">${places.map((x,i)=>`<button data-shelter="${i}"><span><b>${esc(x.name)}</b><small>${esc(x.source)}${x.type==='unknown'?' · tipo da verificare':''}</small></span><strong>${distanceText(x.distance)}</strong></button>`).join('')||'<p>Nessun luogo trovato nel campione. Non significa che non esistano ripari.</p>'}</div><p class="field-note">Edifici e parcheggi cartografati, non rifugi certificati. Non è garantito che siano aperti, accessibili o sicuri durante un evento.</p><a class="field-external" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?${esc(new URLSearchParams({api:'1',query:(category==='car'?'parcheggi coperti vicino a ':'edifici pubblici vicino a ')+(p.source==='gps'?lat+','+lon:p.name)}))}">Cerca anche su Google Maps ↗</a>${d.osmAt?'<p class="field-source">Dati OSM: '+esc(new Date(d.osmAt).toLocaleString('it-IT'))+'</p>':''}${d.truncated?'<p>Risultati community parziali.</p>':''}`);
   document.querySelectorAll('[data-shelter-type]').forEach(b=>b.onclick=()=>shelters(b.dataset.shelterType));document.querySelectorAll('[data-shelter]').forEach(b=>b.onclick=()=>shelterDetail(places[+b.dataset.shelter]));
  }catch(e){if(!dead&&token===shelterToken&&panelToken===o.panelToken())o.panel('Ricerca ripari non disponibile',`<p>${esc(e.message||'Riprova tra poco.')}</p>`);}
 }
 function shelterDetail(p){
  map.setView([p.latitude,p.longitude],14,{animate:false});o.panel(p.name,`<p>${mapIcon('shelter')} ${esc(p.source)} · ${distanceText(p.distance)} in linea d’aria</p><p>${esc(p.details||'Dettagli non presenti nella fonte.')}</p><dl class="field-shelter-details"><dt>Orari dichiarati</dt><dd>${esc(p.openingHours||'Non disponibili')}</dd><dt>Accesso / costo</dt><dd>${esc(p.access||'Da verificare')} · ${esc(p.fee||'Da verificare')}</dd><dt>Posti liberi</dt><dd>Non disponibili</dd></dl><p>Verifica accesso e copertura prima di partire. Le indicazioni stradali non considerano necessariamente allagamenti o pericoli.</p><a class="field-external" target="_blank" rel="noopener" href="${esc(directionsURL(p,p.type==='people'?'people':'car'))}">Indicazioni con Google Maps ↗</a>${p.sourceURL?`<a class="field-external" href="${esc(p.sourceURL)}" target="_blank" rel="noopener">Scheda OpenStreetMap ↗</a>`:''}`);
 }
 expiryTimer=setInterval(()=>{if(!dead&&!document.hidden){render();draw();}},60000);
 return {sync,count:()=>reportState==='ok'?near().length:null,summary:()=>mode==='grandine'?('Grandine entro '+radius+' km da '+place?.name+': '+(reportState==='ok'?near().filter(p=>!p.ended).length+' osservazioni non verificate nel campione':'dati non disponibili')+'. Distanze geografiche, nessuna traiettoria o tempo di impatto disponibile. Ripari ricercabili separatamente entro 5 km, nessuna disponibilità garantita.'):'',refresh(){clearCache();key='';if(place)sync(place,mode);},dispose(){dead=true;life++;shelterToken++;clearInterval(expiryTimer);layer.remove();rings.remove();},close(){if(open){open=false;render();}}};
}
